using System.Text;

namespace DotObj;

internal sealed partial class Emitter
{
    private static void WriteFloat80Access(string output)
    {
        const string source = """
            // <auto-generated />
            #nullable enable
            namespace Edg.Runtime;

            // C volatile binary80 has no atomicity guarantee. These ordered
            // payload accesses remain observable and leave padding untouched.
            public static unsafe class Float80Access
            {
                public static Float80 Read(Float80* address)
                {
                    ulong significand = global::System.Threading.Volatile.Read(ref *(ulong*)address);
                    ushort exponent = global::System.Threading.Volatile.Read(ref *(ushort*)((byte*)address + 8));
                    return new Float80(significand, exponent);
                }

                public static void Write(Float80* address, Float80 value)
                {
                    global::System.Threading.Volatile.Write(ref *(ulong*)address, value.Significand);
                    global::System.Threading.Volatile.Write(ref *(ushort*)((byte*)address + 8), value.SignExponent);
                }
            }
            """;
        File.WriteAllText(Path.Combine(output, "Runtime.Float80Access.generated.cs"), source + "\n", new UTF8Encoding(false));
    }
}
